peloader加载器1.创建数组来保存pe文件中的内容HANDLE X1(char* x, unsigned char** pbuf)&#123;	HANDLE X;	DWORD FileSize;	LPDWORD IFFileSize=0;	LPDWORD IFReadFile=0;	X = CreateFileA(x,		GENERIC_READ,		FILE_SHARE_READ | FILE_SHARE_WRITE,		NULL,		OPEN_EXISTING,		FILE_ATTRIBUTE_NORMAL,		NULL	);	DWORD err= GetLastError();	if (X == INVALID_HANDLE_VALUE)	&#123;		printf(&quot;未能打开文件%d&quot;, err);		exit(0);	&#125;	FileSize = GetFileSize(X, IFFileSize);	if (IFFileSize == -1)	&#123;		printf(&quot;未能得到文件尺寸&quot;);		exit(0);	&#125;    *pbuf =(unsigned char *)malloc(sizeof(unsigned char)* FileSize);	ZeroMemory(*pbuf, FileSize);//清零	ReadFile(X, *pbuf, FileSize, IFReadFile, NULL);	if (IFReadFile == -1)	&#123;		printf(&quot;未能复制文件&quot;);		exit(0);	&#125;&#125;

2.申请内存将DOS头NT头写入PIMAGE_DOS_HEADER DOS = (PIMAGE_DOS_HEADER)pbuf;PIMAGE_NT_HEADERS64 NT = (PIMAGE_NT_HEADERS64)(pbuf + DOS-&gt;e_lfanew);DWORD SizeOfImage = NT-&gt;OptionalHeader.SizeOfImage;LPVOID Alloc;if (NT-&gt;OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress != 0)Alloc = VirtualAlloc(NULL, SizeOfImage, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);elseAlloc = VirtualAlloc(NT-&gt;OptionalHeader.ImageBase, SizeOfImage, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);ZeroMemory(Alloc, SizeOfImage);CopyMemory(Alloc, pbuf, NT-&gt;OptionalHeader.SizeOfHeaders);//申请dos，nt空间

3.将节区循环写入申请内存DWORD SectionNumber = NT-&gt;FileHeader.NumberOfSections;for (DWORD n=0; n &lt; SectionNumber; n++)//复制节区&#123;	PIMAGE_SECTION_HEADER SectionHead = (PIMAGE_SECTION_HEADER)((char*)NT+sizeof(IMAGE_NT_HEADERS64)+ sizeof(IMAGE_SECTION_HEADER)*n);	if (SectionHead-&gt;PointerToRawData!=0)//.bss节区（需要初始化）	CopyMemory(SectionHead-&gt;VirtualAddress + (PCHAR)Alloc, pbuf + SectionHead-&gt;PointerToRawData, SectionHead-&gt;SizeOfRawData);	else	&#123;		ZeroMemory(SectionHead-&gt;VirtualAddress + (PCHAR)Alloc, SectionHead-&gt;Misc.VirtualSize);//清零	&#125;&#125;

