irtualAddress + (PCHAR)Alloc, SectionHead-&gt;Misc.VirtualSize);		&#125;	&#125;	if (NT-&gt;OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress != 0)	&#123;		PIMAGE_BASE_RELOCATION ReLoc = (PIMAGE_BASE_RELOCATION)(NT-&gt;OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress + (PCHAR)Alloc);		while (ReLoc-&gt;SizeOfBlock != 0)		&#123;			PCHAR ReV = ReLoc-&gt;VirtualAddress + (PCHAR)Alloc;			int NumberOfBlock = (ReLoc-&gt;SizeOfBlock - 8) / 2;			for (int n = 0; n &lt; NumberOfBlock; n++)			&#123;				PWORD ChangByte = (PWORD)(ReLoc + 1);				char Type = ChangByte[n] &gt;&gt; 12;				//PDWORD64 Offest = 0;				if (Type == 10)				&#123;					// 找到目标地址					// 修改目标地址的值：方法是原来的值+偏移					PDWORD64 Offest = (PDWORD64*)((ChangByte[n] &amp; 0xfff) + ReV);					*Offest = *Offest + (ULONGLONG)Alloc - NT-&gt;OptionalHeader.ImageBase;				&#125;			&#125;			ReLoc = (PIMAGE_SECTION_HEADER)((PCHAR)ReLoc + ReLoc-&gt;SizeOfBlock);		&#125;	&#125;	PIMAGE_IMPORT_DESCRIPTOR IntImport = (PIMAGE_IMPORT_DESCRIPTOR)(NT-&gt;OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT].VirtualAddress + (PCHAR)Alloc);	while (IntImport-&gt;Name!=0)//引入表	&#123;		HMODULE DllHandle;		char DllName[50];		strncpy(DllName,IntImport-&gt;Name+(PCHAR)Alloc,49);		DllHandle = LoadLibraryA(DllName);		PIMAGE_THUNK_DATA64	INT = IntImport-&gt;OriginalFirstThunk + (PCHAR)Alloc;		PIMAGE_THUNK_DATA64	IAT = IntImport-&gt;FirstThunk + (PCHAR)Alloc;		while (INT-&gt;u1.AddressOfData != 0)		&#123;			if (INT-&gt;u1.Ordinal &amp; IMAGE_ORDINAL_FLAG64)			&#123;				IAT-&gt;u1.AddressOfData = GetProcAddress(DllHandle, INT-&gt;u1.Ordinal);			&#125;				else			&#123;				PIMAGE_IMPORT_BY_NAME Fcn = (PIMAGE_IMPORT_BY_NAME)(INT-&gt;u1.AddressOfData + (PCHAR)Alloc);				IAT-&gt;u1.AddressOfData = GetProcAddress(DllHandle, Fcn-&gt;Name);				int l = 1;			&#125;			INT++;			IAT++;		&#125;		IntImport++;	&#125;	FARPROC EOP = (FARPROC)((LPBYTE)Alloc + NT-&gt;OptionalHeader.AddressOfEntryPoint);	EOP(); 	free